            get => _searchText;
            set
            {
                if (SetProperty(ref _searchText, value))
                {
                    FilterChats();
                }
            }
        }

        public string NewMessageText
        {
            get => _newMessageText;
            set => SetProperty(ref _newMessageText, value);
        }

        public string SelectedChatTitle => SelectedChat?.Title ?? string.Empty;
        public string SelectedChatStatus => SelectedChat?.Interlocutor?.IsOnline == true ? "в сети" : SelectedChat?.Interlocutor?.LastSeenText ?? string.Empty;
        public bool IsChatSelected => SelectedChat != null;

        public ICommand SendMessageCommand { get; }

        public MainViewModel(IDataService dataService)
        {
            _dataService = dataService;
            Chats = new ObservableCollection<Chat>(_dataService.GetChats());
            _filteredChats = new ObservableCollection<Chat>(Chats);
            SendMessageCommand = new RelayCommand(_ => SendMessage(), _ => !string.IsNullOrWhiteSpace(NewMessageText) && SelectedChat != null);
        }

        private void LoadMessages()
        {
            CurrentMessages.Clear();
            if (SelectedChat != null)
            {
                foreach (var msg in SelectedChat.Messages)
                {
                    CurrentMessages.Add(msg);
                }
                SelectedChat.UnreadCount = 0;
                RefreshChatList();
            }
        }

        private void SendMessage()
        {
            if (SelectedChat == null || string.IsNullOrWhiteSpace(NewMessageText)) return;

            var msg = new Message
            {
                Id = CurrentMessages.Count + 100,
                ChatId = SelectedChat.Id,
                SenderId = 1,
                Text = NewMessageText.Trim(),
                Timestamp = System.DateTime.Now,
                IsOwn = true,
                IsRead = true
            };

            _dataService.AddMessage(msg);
            CurrentMessages.Add(msg);
            NewMessageText = string.Empty;
            RefreshChatList();
        }

        private void FilterChats()
        {
            var filtered = string.IsNullOrWhiteSpace(SearchText)
                ? Chats
                : new ObservableCollection<Chat>(Chats.Where(c => c.Title.Contains(SearchText, System.StringComparison.OrdinalIgnoreCase)));

            // Simple refresh for demo
            Chats.Clear();
            foreach (var c in filtered) Chats.Add(c);
        }

        private void RefreshChatList()
        {
            // Trigger UI update for last message preview
            var temp = SelectedChat;
            SelectedChat = null;
            SelectedChat = temp;
        }
    }
}
